def plotar(X_z_scored, Y, w4, w3, w2, w1, b):
        linha_predicao_1 = [ w4 * math.exp(xz) + w3 * math.log(abs(xz) + 1e-8) + w2 * (xz**2) + w1 * xz + b for xz in X_z_scored ]

        # Truque de ordenação: garante que a reta seja desenhada da esquerda para a direita
        pontos_ordenados_1 = sorted(zip(X_z_scored, linha_predicao_1))
        x_ord_1, y_ord_1 = zip(*pontos_ordenados_1)

        plt.figure(figsize = (8,10))
        plt.scatter(X_z_scored, Y, color='green', alpha=0.6, label='Dados Reais (Z-Score)')
        plt.plot(x_ord_1, y_ord_1, color='red', label='Modelo De Regressão Criado A Partir De Dados Lineares', linewidth=2)

        plt.title('Gráfico 1: Dataset Linear')
        plt.xlabel('Desvios Padrão (Z-Score)')
        plt.ylabel('Valor Real (Y)')
        plt.axhline(0, color='black', linewidth=0.5)
        plt.axvline(0, color='black', linewidth=0.5)
        plt.grid(True, linestyle=':', alpha=0.7)
        plt.legend()
        plt.show()

